import ee, math, sys

def safe_init():
    try:
        ee.Initialize(project='earthsense-436113')
        return True
    except Exception as e:
        print("Init error:", str(e)[:120])
        print("D")
        return False

if not safe_init():
    sys.exit(0)

# 1. Geometry & Time Definitions
volcano = ee.Geometry.Point([130.659, 31.593])  # Sakurajima
outer = volcano.buffer(300000)  # 300 km
inner = volcano.buffer(10000)   # 10 km
ring = outer.difference(inner, 1)
start = '2015-05-21'
end   = '2015-05-22'
scale = 3000

def pick_aod_band(col):
    # Try to pick a suitable AOD band available in v061 products
    try:
        first = col.first()
        if first is None:
            return None
        bands = ee.Image(first).bandNames().getInfo()
        candidates = [
            'Optical_Depth_Land_And_Ocean',
            'AOD_550_Dark_Target_Deep_Blue_Combined',
            'AOD_550_Dark_Target',
            'AOD_550_Deep_Blue',
            'Corrected_Optical_Depth_Land',
            'Corrected_Optical_Depth_Ocean'
        ]
        for b in candidates:
            if b in bands:
                return b
        return None
    except Exception:
        return None

def process_aod(coll_id, label):
    try:
        col = ee.ImageCollection(coll_id).filterDate(start, end).filterBounds(volcano)
        n = col.size().getInfo()
        print(f"{label} images: {n}")
        if n == 0:
            # Try +/-1 day fallback
            col_fb = ee.ImageCollection(coll_id).filterDate('2015-05-20', '2015-05-23').filterBounds(volcano)
            n2 = col_fb.size().getInfo()
            print(f"{label} fallback images: {n2}")
            if n2 == 0:
                return {'status':'C1'}
            col = col_fb

        band = pick_aod_band(col)
        if band is None:
            return {'status':'D'}

        img = col.select([band]).mosaic().rename('aod')
        # Keep only non-negative AOD
        aod = img.updateMask(img.gte(0)).rename('aod')

        def stats_for_threshold(thr):
            sel = aod.updateMask(aod.gt(thr))
            # Count valid (masked-in) pixels
            cnt = sel.reduceRegion(
                reducer=ee.Reducer.count(),
                geometry=ring,
                scale=scale,
                maxPixels=1e9
            ).get('aod')
            cnt = None if cnt is None else int(ee.Number(cnt).getInfo())
            return sel, cnt

        # Try strict then relaxed threshold
        thr = 0.30
        sel, count = stats_for_threshold(thr)
        if (count is None) or (count == 0):
            thr = 0.15
            sel, count = stats_for_threshold(thr)
            if (count is None) or (count == 0):
                print(f"{label} valid px: 0 (after masking)")
                return {'status':'C2'}

        # Weighted centroid by AOD
        latlon = ee.Image.pixelLonLat()
        sumw = sel.reduceRegion(
            reducer=ee.Reducer.sum(),
            geometry=ring,
            scale=scale,
            maxPixels=1e9
        ).get('aod')
        if sumw is None:
            return {'status':'C3'}
        sumw = float(ee.Number(sumw).getInfo())
        if sumw == 0 or math.isnan(sumw):
            return {'status':'C3'}

        lonw = latlon.select('longitude').multiply(sel).rename('lonw')
        latw = latlon.select('latitude').multiply(sel).rename('latw')
        sum_lonw = lonw.reduceRegion(
            reducer=ee.Reducer.sum(),
            geometry=ring,
            scale=scale,
            maxPixels=1e9
        ).get('lonw')
        sum_latw = latw.reduceRegion(
            reducer=ee.Reducer.sum(),
            geometry=ring,
            scale=scale,
            maxPixels=1e9
        ).get('latw')
        if sum_lonw is None or sum_latw is None:
            return {'status':'C3'}
        lon_c = float(ee.Number(sum_lonw).getInfo())/sumw
        lat_c = float(ee.Number(sum_latw).getInfo())/sumw
        if any(v is None or math.isnan(v) for v in [lon_c, lat_c]):
            return {'status':'C3'}

        # Compute offsets from volcano (meters)
        lon0, lat0 = 130.659, 31.593
        dx_deg = lon_c - lon0
        dy_deg = lat_c - lat0
        dx_m = dx_deg * 111320.0 * math.cos(math.radians(lat0))
        dy_m = dy_deg * 110540.0

        print(f"{label} thr: {thr:.2f}, valid px: {count}, centroid: ({lat_c:.3f},{lon_c:.3f}), dx: {dx_m:.0f} m, dy: {dy_m:.0f} m")
        return {'status':'OK', 'dx':dx_m, 'dy':dy_m, 'count':count}
    except ee.EEException as e:
        print("Error:", str(e)[:120])
        return {'status':'D'}
    except Exception as e:
        print("Error:", str(e)[:120])
        return {'status':'D'}

try:
    terra = process_aod('MODIS/061/MOD04_3K', 'Terra AOD')
    aqua  = process_aod('MODIS/061/MYD04_3K', 'Aqua AOD')

    # Handle status aggregation
    statuses = [terra.get('status'), aqua.get('status')]
    if 'D' in statuses:
        print("D"); sys.exit(0)
    if 'C1' in statuses:
        print("C1"); sys.exit(0)
    if 'C2' in statuses:
        print("C2"); sys.exit(0)
    if 'C3' in statuses:
        print("C3"); sys.exit(0)

    # Decision logic: dominance with a 10% margin
    tdx, tdy = terra['dx'], terra['dy']
    adx, ady = aqua['dx'], aqua['dy']
    terra_east  = (tdx > 0) and (abs(tdx) >= 1.1*abs(tdy))
    terra_south = (tdy < 0) and (abs(tdy) >= 1.1*abs(tdx))
    aqua_east   = (adx > 0) and (abs(adx) >= 1.1*abs(ady))
    aqua_south  = (ady < 0) and (abs(ady) >= 1.1*abs(adx))
    print(f"Dominance -> Terra(E,S): {int(terra_east)},{int(terra_south)}  Aqua(E,S): {int(aqua_east)},{int(aqua_south)}")

    if terra_east and aqua_south:
        print("A")
    else:
        print("B")
except ee.EEException as e:
    print("Error:", str(e)[:120])
    print("D")
except Exception as e:
    print("Error:", str(e)[:120])
    print("D")
